#!/usr/bin/env python3
"""Audit docs/ pour Docusaurus (sidebar autogenerated) ; --fix crée les _category_.json manquants.

Usage: python3 sync_structure.py [docs_dir] [--fix]
Ne modifie jamais un _category_.json existant ni un fichier markdown.
Code retour 1 s'il reste des problèmes bloquants (JSON invalide, dossier sans catégorie).
"""
import json, re, sys
from pathlib import Path

args = [a for a in sys.argv[1:] if not a.startswith("--")]
fix = "--fix" in sys.argv
root = Path(args[0] if args else "docs")
errors, warnings, created = [], [], []

def frontmatter(p):
    m = re.match(r"---\n(.*?)\n---", p.read_text(encoding="utf-8"), re.S)
    return dict(re.findall(r"^(\w+):\s*(.+)$", m.group(1), re.M)) if m else {}

def cat_pos(d):
    try: return json.loads((d / "_category_.json").read_text(encoding="utf-8")).get("position")
    except (OSError, json.JSONDecodeError): return None

def has_docs(d):
    return any(d.rglob("*.md")) or any(d.rglob("*.mdx"))

def walk(d):
    positions = {}  # position -> [noms] pour les frères (fichiers + sous-catégories)
    for child in sorted(d.iterdir()):
        if child.name.startswith((".", "_")) and child.is_file():
            continue
        if child.is_dir() and not child.name.startswith("."):
            cat = child / "_category_.json"
            if not has_docs(child):
                warnings.append(f"{child}: aucun .md/.mdx (dossier vide, invisible dans la sidebar)")
                continue
            if cat.exists():
                pos = cat_pos(child)
                if pos is None and not cat.read_text(encoding="utf-8").strip().startswith("{\"") and "position" not in cat.read_text():
                    errors.append(f"{cat}: JSON invalide ou sans position")
                if pos is not None: positions.setdefault(pos, []).append(child.name + "/")
            else:
                pos = max([q for q in positions if isinstance(q, int)] + [cat_pos(s) or 0 for s in d.iterdir() if s.is_dir()]) + 1
                if fix:
                    cat.write_text(json.dumps({"label": child.name, "position": pos}, ensure_ascii=False)
                                   .replace("{", "{ ").replace("}", " }") + "\n", encoding="utf-8")
                    created.append(f"{cat} (label={child.name}, position={pos})")
                    positions.setdefault(pos, []).append(child.name + "/")
                else:
                    errors.append(f"{child}: _category_.json manquant (--fix le crée, position {pos})")
            walk(child)
        elif child.suffix in (".md", ".mdx"):
            fm = frontmatter(child)
            if "title" not in fm: warnings.append(f"{child}: pas de title (le nom de fichier sera affiché)")
            if "sidebar_position" in fm:
                try: positions.setdefault(int(fm["sidebar_position"]), []).append(child.name)
                except ValueError: warnings.append(f"{child}: sidebar_position non numérique")
            else:
                warnings.append(f"{child}: pas de sidebar_position (tri alphabétique)")
    for pos, names in positions.items():
        if len(names) > 1:
            warnings.append(f"{d}: position {pos} en double -> {', '.join(names)}")

walk(root)
for label, items in (("CRÉÉ", created), ("ERREUR", errors), ("AVERTISSEMENT", warnings)):
    for i in items: print(f"[{label}] {i}")
if not (created or errors or warnings): print("Structure OK")
sys.exit(1 if errors else 0)
